package reset

import chisel3._
import chisel3.util._
import chiselFv._

/**
 * A simple module that demonstrates reset properties.
 * After reset, the counter starts at 0 and increments each cycle.
 * When it reaches a max value, it wraps around.
 * Formal assertions verify reset behavior and counter properties.
 */
class ResetModule extends Module with Formal {
  val io = IO(new Bundle {
    val en  = Input(Bool())
    val max = Input(UInt(8.W))
    val out = Output(UInt(8.W))
    val wrap = Output(Bool())
  })

  // Counter register
  val count = RegInit(0.U(8.W))
  val wrap_detected = RegInit(false.B)

  // Counter logic
  when(io.en) {
    when(count === io.max) {
      count := 0.U
      wrap_detected := true.B
    }.otherwise {
      count := count + 1.U
    }
  }.otherwise {
    // When disabled, count holds its value (normal behavior)
    // Only reset explicitly via the hardware reset
  }

  io.out := count
  io.wrap := wrap_detected

  // ============================================
  // Formal Verification Assertions
  // ============================================

  // --- Safety Property 1: Counter value stays in valid range ---
  // After reset, the counter is 0 and never exceeds max
  fvAssert(count <= io.max, "counter_never_exceeds_max")

  // --- Safety Property 2: After reset, count is 0 ---
  // assertAt checks the condition exactly at the specified cycle after reset
  assertAt(0.U, count === 0.U, "count_zero_after_reset")

  // --- Safety Property 3: Counter increments only when enabled ---
  // When enabled and not wrapping, count increases by 1
  // When disabled, count stays the same
  when(io.en) {
    when(count === io.max) {
      fvAssert(count === 0.U, "wrap_resets_count")
    }.otherwise {
      // Assert that if enabled and not at max, next count = current + 1
      // We can't directly check next state in ChiselFV easily,
      // but we can check the registered value
    }
  }

  // --- Safety Property 4: wrap signal implies count is at max ---
  // Check that when wrap fires, the counter was at max
  // This uses assertOnRise: on rising edge of wrap, count must be at max
  // Actually wrap is combinatorial, let's use a simpler approach

  // --- Safety Property 5: Mutex between normal counting and wrapping ---
  // When enabled, exactly one of these holds: count==max or count<max
  // This is trivially true given the counter logic

  // --- Liveness/Progress Property: Counter eventually reaches max ---
  // If enabled continuously, the counter should eventually reach max
  // Using astRelaxedLiveness with a timeout of 300 cycles (max value is 255)
  // Request: enabled and count < max
  // Response: count reaches max (or we disable which also satisfies the property)
  astRelaxedLiveness(
    io.en && count < io.max,
    count === io.max || !io.en,
    300,
    "counter_eventually_reaches_max"
  )

  // --- Liveness: When enabled, count should never stay stuck forever ---
  // If enabled and count is at some value, it should eventually change
  astRelaxedLiveness(
    io.en,
    count === 0.U || !io.en,
    300,
    "counter_makes_progress"
  )

  // --- Safety: After wrapping, max value is preserved ---
  // The max input should be stable during operation
  // (This is a simple check that max doesn't change unexpectedly)
  // Can't easily check this without past values in pure ChiselFV

  // --- One-hot check is not applicable for a counter ---

  // --- Stability check: when not enabled, count stays stable ---
  assertStableWhen(!io.en, count, "count_stable_when_disabled")

  // --- Counter value is never negative (unsigned) ---
  // Trivially true for UInt, but good for documentation
  // fvAssert(count >= 0.U, "count_non_negative") -- UInt always >= 0, trivial
}

/**
 * VerilogGenerator emits the ResetModule
 * This is the entry point used by make verilog
 */
object VerilogGenerator extends App {
  emitVerilog(new ResetModule(), Array("--target-dir", "generated"))
}

